3.2 Pool的工作原理Get操作：
首先尝试从本地Pool获取对象如果本地Pool为空，尝试从全局Pool获取如果全局Pool也为空，调用New函数创建新对象Put操作：
将对象放入本地Pool如果本地Pool已满，将对象放入全局PoolGC清理：
在GC时，Pool中的所有对象都会被清理这是为了防止Pool中的对象占用过多内存4. Pool的高级用法4.1 自定义对象创建go体验AI代码助手代码解读复制代码package main
import ("fmt""sync")
type Buffer struct {Data []byteSize int}
var bufferPool = sync.Pool{New: func() interface{} {fmt.Println("Creating new buffer")return &Buffer{Data: make([]byte, 0, 1024),Size: 0,}},}
func getBuffer() *Buffer {buf := bufferPool.Get().(*Buffer)buf.Data = buf.Data[:0] // 重置但不释放底层数组buf.Size = 0return buf}
func putBuffer(buf *Buffer) {bufferPool.Put(buf)}
func main() {// 获取缓冲区buf := getBuffer()buf.Data = append(buf.Data, "Hello, World!"...)buf.Size = len(buf.Data)fmt.Printf("Buffer: %s, Size: %d\n", string(buf.Data), buf.Size)
// 放回Pool putBuffer(buf) // 再次获取 buf2 := getBuffer() fmt.Printf("Buffer capacity: %d\n", cap(buf2.Data)) putBuffer(buf2)
}
