func main() {// 测试使用Pool的性能start := time.Now()withPool()duration1 := time.Since(start)
// 测试不使用Pool的性能 start = time.Now() withoutPool() duration2 := time.Since(start) fmt.Printf("With Pool: %v\n", duration1) fmt.Printf("Without Pool: %v\n", duration2)
}
