import ("database/sql""fmt""sync")
type DBConnection struct {Conn *sql.DBID int}
var connPool = sync.Pool{New: func() interface{} {// 创建新的数据库连接return &DBConnection{Conn: nil,ID: 0,}},}
func getConnection() *DBConnection {conn := connPool.Get().(*DBConnection)if conn.Conn == nil {// 初始化连接fmt.Println("Initializing new connection")}return conn}
func putConnection(conn *DBConnection) {// 重置连接状态conn.ID = 0connPool.Put(conn)}
func main() {// 获取连接conn := getConnection()fmt.Printf("Connection ID: %d\n", conn.ID)
// 使用连接 conn.ID = 1 // 放回Pool putConnection(conn) // 再次获取 conn2 := getConnection() fmt.Printf("Connection ID: %d\n", conn2.ID) putConnection(conn2)
}
