import ("bytes""fmt""sync")
var bufferPool = sync.Pool{New: func() interface{} {return new(bytes.Buffer)},}
func processData(data []byte) string {// 从Pool获取缓冲区buf := bufferPool.Get().(*bytes.Buffer)defer bufferPool.Put(buf)
// 重置缓冲区 buf.Reset() // 处理数据 buf.Write(data) buf.WriteString(" - processed") return buf.String()
}
func main() {// 处理多个数据datas := [][]byte{[]byte("Hello"),[]byte("World"),[]byte("Go"),[]byte("Language"),}
for _, data := range datas { result := processData(data) fmt.Println(result) }
}
